    const query = new URLSearchParams();

    if (params?.search) {
      query.set('search', params.search);
    }

    if (
      params?.category &&
      params.category !== 'all'
    ) {
      query.set('category', params.category);
    }

    const qs = query.toString();

    return apiList<ApiBook>(
      `/books/${qs ? `?${qs}` : ''}`
    );
